class _C:
    eqs = 0

    def __init__(self, v):
        self.v = v

    def __eq__(self, other):
        _C.eqs += 1
        return isinstance(other, _C) and self.v == other.v

    def __hash__(self):
        return hash(self.v)

a = [_C(i) for i in range(400)]
b = [_C(i) for i in range(200, 600)]
_C.eqs = 0
result = common_items(a, b)
assert [x.v for x in result] == list(range(200, 400))
assert _C.eqs < 2000, f'common_items compared items {_C.eqs} times; a set answers `in` without scanning every item'

steps.solution:
def common_items(a, b):
    seen = set(a)
    return [item for item in b if item in seen]
